-- Keep invalid clinical domains as HTTP400, but classify a second DOCTOR
-- clinical identity as the HTTP409 capacity conflict used by the API contract.
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO
ALTER PROCEDURE dbo.usp_organization_member_save @tenant_id char(36),@user_id char(36),@input nvarchar(max)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_org_target @tenant_id,@write=1; EXEC dbo.usp_org_json_object @input,N'{"roles":4,"status":1,"branches":4,"specialties":4}'; DECLARE @roles nvarchar(max),@status nvarchar(max),@branches nvarchar(max),@codes nvarchar(max),@domain nvarchar(6),@kind nvarchar(40),@ownerid char(36),@quota int,@used int,@owner bit,@oldpro bit=0,@newpro bit=0,@userdomain nvarchar(6); SELECT @roles=roles,@status=status,@branches=branches,@codes=specialties FROM OPENJSON(@input) WITH(roles nvarchar(max) AS JSON,status nvarchar(max),branches nvarchar(max) AS JSON,specialties nvarchar(max) AS JSON); EXEC dbo.usp_org_json_strings @roles,3,N'["ADM","REC","PRO","ASI","DIA","FAR","CAJ","ALM","PAC","RES","AUD"]'; EXEC dbo.usp_org_json_strings @branches,36; EXEC dbo.usp_org_json_strings @codes,100,@nonempty=0; IF DATALENGTH(@status)<>2*LEN(@status) OR @status COLLATE Latin1_General_100_BIN2 NOT IN ('ACTIVE','INVITED','INACTIVE') THROW 51000,'HP_INVALID:Estado de miembro invalido',1; SELECT @domain=domain,@kind=kind,@ownerid=owner_user_id FROM dbo.tenants WHERE id=@tenant_id; SELECT @quota=professional_quota FROM dbo.subscriptions WHERE tenant_id=@tenant_id; IF NOT EXISTS(SELECT 1 FROM dbo.users WITH(UPDLOCK,HOLDLOCK) WHERE id=@user_id AND active=1 AND platform_role IS NULL) THROW 51002,'HP_NOT_FOUND:Identidad no disponible',1; SELECT @userdomain=clinical_domain FROM dbo.users WHERE id=@user_id; SELECT @owner=owner,@oldpro=CASE WHEN status<>'INACTIVE' AND EXISTS(SELECT 1 FROM OPENJSON(roles) WHERE value='PRO') THEN 1 ELSE 0 END FROM dbo.memberships WITH(UPDLOCK,HOLDLOCK) WHERE tenant_id=@tenant_id AND user_id=@user_id; IF EXISTS(SELECT 1 FROM OPENJSON(@roles) WHERE value='PRO') BEGIN IF (@status<>'INACTIVE' AND (@userdomain IS NULL OR @userdomain<>@domain)) THROW 51000,'HP_INVALID:Identidad profesional incompatible',1; IF @kind='DOCTOR' AND @user_id<>@ownerid THROW 51003,'HP_CONFLICT:HP_QUOTA Una identidad clinica por profesional independiente',1; IF @status<>'INACTIVE' SET @newpro=1; END; SELECT @used=COUNT(*) FROM dbo.memberships m WHERE m.tenant_id=@tenant_id AND m.status<>'INACTIVE' AND EXISTS(SELECT 1 FROM OPENJSON(m.roles) WHERE value='PRO'); IF @newpro=1 AND @oldpro=0 AND @used>=@quota THROW 51003,'HP_CONFLICT:HP_QUOTA Sin licencias profesionales disponibles',1; IF @owner=1 AND (@status<>'ACTIVE' OR NOT EXISTS(SELECT 1 FROM OPENJSON(@roles) WHERE value='ADM')) THROW 51000,'HP_INVALID:Conserva administrador propietario activo',1; IF EXISTS(SELECT 1 FROM OPENJSON(@branches) j WHERE DATALENGTH(j.value)<>72 OR TRY_CONVERT(uniqueidentifier,j.value) IS NULL OR NOT EXISTS(SELECT 1 FROM dbo.branches b WHERE b.tenant_id=@tenant_id AND b.id=j.value COLLATE Latin1_General_100_BIN2 AND b.active=1)) THROW 51000,'HP_INVALID:Asigna sedes activas del mismo tenant',1; IF EXISTS(SELECT 1 FROM OPENJSON(@roles) WHERE value='PRO') AND ((@newpro=1 AND NOT EXISTS(SELECT 1 FROM OPENJSON(@codes))) OR EXISTS(SELECT 1 FROM OPENJSON(@codes) j WHERE NOT EXISTS(SELECT 1 FROM dbo.tenant_specialties ts WHERE ts.tenant_id=@tenant_id AND ts.specialty_code=j.value COLLATE Latin1_General_100_BIN2))) THROW 51000,'HP_INVALID:Asigna especialidades activadas del tenant',1; IF NOT EXISTS(SELECT 1 FROM dbo.memberships WHERE tenant_id=@tenant_id AND user_id=@user_id) INSERT dbo.memberships(tenant_id,user_id,roles,status,owner) VALUES(@tenant_id,@user_id,@roles,@status,0); ELSE UPDATE dbo.memberships SET roles=@roles,status=@status WHERE tenant_id=@tenant_id AND user_id=@user_id; DELETE dbo.membership_branches WHERE tenant_id=@tenant_id AND user_id=@user_id; INSERT dbo.membership_branches(tenant_id,user_id,branch_id) SELECT @tenant_id,@user_id,value FROM OPENJSON(@branches); DELETE dbo.membership_specialties WHERE tenant_id=@tenant_id AND user_id=@user_id; IF EXISTS(SELECT 1 FROM OPENJSON(@roles) WHERE value='PRO') INSERT dbo.membership_specialties(tenant_id,user_id,specialty_code) SELECT @tenant_id,@user_id,value FROM OPENJSON(@codes); DECLARE @meta nvarchar(max)=(SELECT @status status FOR JSON PATH,WITHOUT_ARRAY_WRAPPER); EXEC dbo.usp_audit_event @tenant_id,N'MEMBERSHIP_SAVED',@user_id,@meta; SELECT u.id,u.name,u.email,u.clinical_domain,m.roles,m.status,m.owner FROM dbo.memberships m JOIN dbo.users u ON u.id=m.user_id WHERE m.tenant_id=@tenant_id AND m.user_id=@user_id;
END;
GO
